import {
  AddPickupStationPayload,
  DropOffDetails,
  DropOffLocationResponse,
  DropOffStation,
  EditDropOffStationPayload,
  ErrorrResponse,
  Response,
} from "@/types";
import { api } from "../axios";
import { useMutation } from "@tanstack/react-query";
import { queryClient } from "../queryClient";
import toast from "react-hot-toast";
import axios from "axios";
import { store } from "@/lib/store";
import { updateDropOffDetails } from "@/lib/store/slices/drop-off-station-slice";

export interface DropOffPayload {
  status: string;
  drop_off_station_id: string;
}

export const getDropOffStations = async (
  page: number = 1,
  limit: number = 10,
  search?: string,
  status?: string,
): Promise<DropOffDetails> => {
  try {
    const params = new URLSearchParams({
      page: page.toString(),
      limit: limit.toString(),
    });

    if (search) params.append("search", search);
    if (status && status !== "all") params.append("status", status);

    const res = await api.get(
      `/api/users/admin/drop-off-station/get?${params.toString()}`,
    );
    return res.data;
  } catch (error) {
    console.error("Fetch User Error:", error);
    throw error;
  }
};

export const useCreateDropOffStation = () => {
  return useMutation({
    mutationFn: async (data: AddPickupStationPayload) => {
      const res = await api.post("/api/users/admin/drop-off-station/create", {
        address: data.address,
        area: data.area,
        state: data.state,
        country: data.country,
      });
      return res.data;
    },
    onSuccess: (data: DropOffLocationResponse) => {
      queryClient.invalidateQueries({ queryKey: ["dropOffStations"] });
      toast.success(`${data.message}`);
      return data;
    },
    onError: (error, variables) => {
      if (axios.isAxiosError(error)) {
        const err = error.response?.data as ErrorrResponse;
        console.log("User Erro", error);

        toast.error(`${err?.error.message}`);
      } else {
        console.error("❌ Unexpected error:", error);
      }
    },
  });
};

